'use client';

import React, { createContext, useContext, useEffect, useState } from 'react';
import { createClient } from '@/lib/supabase/client';
import { Session, User } from '@supabase/supabase-js';
import { useRollbar } from '@rollbar/react';
import { setRollbarPerson } from '@/lib/rollbar/user-context';

type AuthContextType = {
    user: User | null;
    session: Session | null;
    loading: boolean;
    error: Error | null;
    signOut: () => Promise<void>;
};

const AuthContext = createContext<AuthContextType>({
    user: null,
    session: null,
    loading: true,
    error: null,
    signOut: async () => { },
});

export const AuthProvider = ({ children }: { children: React.ReactNode }) => {
    const [user, setUser] = useState<User | null>(null);
    const [session, setSession] = useState<Session | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<Error | null>(null);
    const supabase = createClient();
    const rollbar = useRollbar();

    useEffect(() => {
        const setData = async () => {
            try {
                const { data: { session }, error } = await supabase.auth.getSession();
                if (error) throw error;
                setSession(session);
                setUser(session?.user ?? null);
                setRollbarPerson(rollbar, session?.user);
                setLoading(false);
            } catch (err: any) {
                setError(err);
                rollbar.error(err);
                setLoading(false);
            }
        };

        const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
            setSession(session);
            setUser(session?.user ?? null);
            setRollbarPerson(rollbar, session?.user);
            setLoading(false);
        });

        setData();

        return () => {
            subscription.unsubscribe();
        };
    }, [rollbar, supabase.auth]);

    const signOut = async () => {
        try {
            await supabase.auth.signOut();
            setRollbarPerson(rollbar, null);
        } catch (err: any) {
            rollbar.error(err);
        }
    };

    return (
        <AuthContext.Provider value={{ user, session, loading, error, signOut }}>
            {children}
        </AuthContext.Provider>
    );
};

export const useAuth = () => useContext(AuthContext);
